import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_unit_fractions(x):
    """Calculates the number of positive integers y such that 1/x + 1/y is a unit fraction."""
    factors = prime_factorization(x)
    # Tau(x^2) = Product (2*a_i + 1)
    tau_x_squared = 1
    for prime, exponent in factors.items():
        tau_x_squared *= (2 * exponent + 1)

    # The number of solutions y is tau(x^2) - 1 (excluding d=x)
    return tau_x_squared - 1

# Candidates
